"""Build the local geometry evidence board; never marks the block complete."""
import json,html
from pathlib import Path
O=Path('build/resort-blocks/cosmo');record=json.loads(Path('tools/resort-blocks/cosmopolitan.json').read_text());audit=json.loads((O/'route-audit.json').read_text());owner=json.loads((O/'ownership-report.json').read_text());e=html.escape
cards=[]
for name,label,kind in [('game-boulevard.jpg','Level 4 · Boulevard Pool','Installed game'),('game-chelsea.jpg','Level 14 · Chelsea Pool','Installed game'),('game-stair-L2.jpg','Level 2 reached by walking upstairs','Installed game'),('game-level3.jpg','Level 3 · restaurant circulation','Installed game'),('game-entrance.jpg','Strip entrance and arrival','Installed game'),('aerial-review.png','Two independent towers and stacked podium','Exported meshes · neutral daylight'),('gallery-review.png','Level 2 gallery and Chandelier void','Exported meshes · neutral daylight')]:
 if (O/name).exists():cards.append(f'<figure><small>{kind}</small><a href="{name}"><img src="{name}" loading="lazy" alt="{e(label)}"></a><figcaption>{e(label)}</figcaption></figure>')
levels=''.join(f'<tr><td>{e(l["label"])}</td><td>{l["elevationM"]:.2f} m*</td><td>{e(l["features"])}</td><td><a href="/?resortReview=1&landmark=cosmo{l["id"]}">Visit</a></td></tr>' for l in record['levels'] if l['id'] in ('L1','L2','L3','L4','L14'))
sources=''.join(f'<li><a href="{e(s["url"])}">{e(s["title"])}</a></li>' for s in record['sources'] if s.get('url') and (s['id'].startswith('map-') or s['id'] in ('architect','boulevard-pool','chelsea-pool','overlook')))
open_items=''.join(f'<li>{e(c["name"])}: {e(c.get("note",c["scope"]))}</li>' for c in record['components'] if c['status'] in ('planned','partial'))
content=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cosmopolitan · Geometry proof</title><style>
:root{{color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:#101b20;color:#e9eeeb;font:16px/1.55 system-ui}}main{{max-width:1500px;margin:auto;padding:40px}}h1{{font-size:clamp(30px,4vw,58px);line-height:1.05;margin:14px 0}}h2{{margin-top:50px}}p{{max-width:950px;color:#becbce}}a{{color:#90d1c4}}.eyebrow,small{{text-transform:uppercase;letter-spacing:.12em;color:#91bbaf;font-size:12px}}.metrics,.grid{{display:grid;grid-template-columns:1fr 1fr;gap:24px}}.metrics{{grid-template-columns:repeat(4,1fr);margin:30px 0}}.metric{{padding:20px;background:#1b2b31;border-top:2px solid #8db7a7}}strong{{display:block;font-size:28px}}figure{{margin:0;background:#192930;padding:16px;border:1px solid #304147}}img{{display:block;width:100%;height:auto;margin:10px 0}}figcaption{{font-weight:600}}table{{border-collapse:collapse;width:100%}}td,th{{padding:14px;text-align:left;border-bottom:1px solid #34444a}}td:first-child{{min-width:180px}}.note{{padding:20px;border-left:3px solid #c5a46c;background:#292923}}li{{margin:8px 0}}@media(max-width:850px){{main{{padding:22px}}.grid,.metrics{{grid-template-columns:1fr}}table{{font-size:13px}}}}
</style><main><div class="eyebrow">Vegas: Afterlight · local geometry build · 5 October 2026</div><h1>Cosmopolitan is now physical geometry.</h1><p>The old stretched assembly has been replaced with individually fitted tower plans, a multi-storey podium, actual slabs and soffits, walkable stairs, arrival spaces and furnished outdoor decks. This page separates implemented geometry from remaining architectural accuracy work.</p>
<div class="metrics"><div class="metric"><strong>5</strong>mapped public levels built</div><div class="metric"><strong>{len(audit['stairWalks'])}/16</strong>stair ascent/descent simulations</div><div class="metric"><strong>{audit['checks']:,}</strong>floor and clearance probes</div><div class="metric"><strong>{owner['removedLegacyBatches']}</strong>legacy mesh owners removed</div></div>
<p><a href="/?resortReview=1&landmark=cosmoL4">Open the playable block with level review controls →</a> · <a href="route-audit.json">Route results</a> · <a href="ownership-report.json">Replacement ledger</a> · <a href="performance.json">Measured performance</a></p>
<h2>Installed build and exported geometry</h2><div class="grid">{''.join(cards)}</div>
<h2>Reference and fitted massing</h2><div class="grid"><figure><small>Creator’s Google Earth reference · image date unknown</small><img src="/tools/resort-blocks/references/cosmopolitan-user-earth.png" alt="Reference showing both Cosmopolitan towers and Jockey Club"><figcaption>Folded Chelsea slab, separate Boulevard tower and northern low-rise context.</figcaption></figure><figure><small>Exported replacement · neutral daylight</small><img src="aerial-review.png" alt="Actual exported Cosmopolitan replacement geometry"><figcaption>Direct geographic footprints; no whole-site nonuniform stretching.</figcaption></figure></div>
<h2>Real floors, separate from numbered labels</h2><table><tr><th>Mapped level</th><th>Elevation</th><th>Scope</th><th>Game</th></tr>{levels}</table><p>* These elevations and stair positions are fitted estimates. Official floor maps establish names and program, not surveyed vertical dimensions. Pools currently have safe shallow collision surfaces, rather than a swimming mechanic.</p>
<h2>What the checks prove</h2><p>{len(audit['failures'])} route probe failures. All stair flights are exercised in both directions with Rapier’s character controller, and the player also walked from Level 1 to Level 2 in the actual game. Floor/clearance probes include surrounding city collision; they do not establish photo accuracy or replace a complete door/camera walkthrough. Decorations stream by level; permanent floors, stairs and envelope stay present.</p>
<h2>Still open before this block is signed off</h2><div class="note">This is the installed geometry proof, not a claim of a complete photorealistic resort. Cosmopolitan remains the active block.</div><ul>{open_items}</ul><p>Further matching is needed for shopfronts, crown detailing, pool tiers and exact terrace layouts. No before/after route benchmark was captured; the recorded warm frame samples are not a guaranteed 60 fps result. Do not promote this block based only on passing geometry probes.</p>
<h2>Official visual and floor-map references</h2><ul>{sources}</ul><p><a href="../index.html">Full component inventory and remaining gates →</a></p></main></html>'''
(O/'proof.html').write_text(content)
print(O/'proof.html')
